PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS courses (id INTEGER PRIMARY KEY, code TEXT NOT NULL UNIQUE COLLATE NOCASE, name TEXT NOT NULL, year INTEGER NOT NULL CHECK(year BETWEEN 1 AND 5), source TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS offerings (id INTEGER PRIMARY KEY, course_id INTEGER NOT NULL REFERENCES courses(id), term TEXT NOT NULL, professor TEXT NOT NULL DEFAULT '', UNIQUE(course_id,term,professor));
CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY);
INSERT OR IGNORE INTO schema_migrations VALUES (1);
